        { type: 'input', q: 'Сколько секунд по правилу 20–20–20 нужно смотреть вдаль?', c: 20, why: '20 секунд — достаточно, чтобы глазные мышцы расслабились.' },
        { type: 'tf', q: 'Играть с ярким экраном в полной темноте — полезно для глаз.', c: false, why: 'Лучше включить свет в комнате: глазам легче.' },
        { type: 'one', q: 'Как правильно сидеть за компьютером?', a: ['Спина на спинке, ноги на полу', 'Лёжа на животе', 'Сгорбившись у экрана', 'Стоя на стуле'], c: 0, why: 'Ровная спина и ноги на полу берегут спину и шею.' },
        { type: 'one', q: 'На каком расстоянии держать экран компьютера?', a: ['Вплотную к носу', 'Примерно на вытянутой руке', 'В другой комнате', 'Неважно'], c: 1, why: 'Вытянутая рука — удобное расстояние для глаз.' },
        { type: 'tf', q: 'Когда долго смотришь в экран, моргаешь реже — и глаза сохнут.', c: true, why: 'Поэтому полезно делать перерывы и специально поморгать.' },
        { type: 'case', story: 'Мурлок уже час играет на планшете, глаза покраснели и щиплет.', q: 'Что сделать?', a: [{ t: 'Отложить планшет, посмотреть в окно, поморгать', ok: true, why: 'Глазам нужен перерыв — дай им отдохнуть.' }, { t: 'Поднести планшет ближе', ok: false, why: 'Так глаза устанут ещё сильнее.' }, { t: 'Играть дальше, но прищуриться', ok: false, why: 'Прищуривание не помогает. Нужен перерыв.' }], why: 'Устали глаза — перерыв. Если такое часто — к окулисту.' },
        { type: 'sort', q: 'Что бережёт глаза, а что утомляет?', groups: ['Бережёт', 'Утомляет'], items: [['Перерыв каждые 20–30 минут', 0], ['Экран в темноте', 1], ['Прогулка днём', 0], ['Телефон у самого носа', 1], ['Смотреть вдаль', 0], ['Три часа игры без перерыва', 1]], why: 'Перерывы, дальние взгляды и дневной свет — друзья глаз.' },
        { type: 'one', q: 'Что делать, если плохо видно доску в классе?', a: ['Молчать', 'Сказать взрослым и сходить к окулисту', 'Сесть ещё дальше', 'Тереть глаза'], c: 1, why: 'Окулист проверит зрение и подскажет, нужны ли очки.' },
        { type: 'order', q: 'Расставь шаги перерыва от экрана.', items: ['Отвести взгляд от экрана', 'Посмотреть вдаль 20 секунд', 'Поморгать несколько раз', 'Встать и потянуться'], why: 'Взгляд вдаль, моргание и движение — полный перерыв.' },
        { type: 'one', q: 'Что значит правило 20–20–20 для глаз?', a: ['Каждые 20 секунд моргать по 20 раз', 'Каждые 20 минут смотреть вдаль 20 секунд', 'Держать экран в 20 см от глаз', 'Играть не больше 20 минут в день'], c: 1, why: 'Каждые 20 минут у экрана нужно секунд 20 смотреть на что-то далёкое, примерно в 6 метрах. Так мышцы глаз расслабляются и меньше устают.' },
        { type: 'one', q: 'Зачем специально моргать во время перерыва?', a: ['Чтобы смочить глаза', 'Чтобы рассмешить друга', 'Чтобы уснуть', 'Незачем'], c: 0, why: 'Моргание смачивает глаз, а у экрана мы моргаем реже.' },
        { type: 'tf', q: 'В упражнении «близко-далеко» смотрят то на кончик пальца, то на дальний предмет.', c: true, why: 'Так глазные мышцы то напрягаются, то расслабляются.' },
        { type: 'sort', q: 'Где лучше без экранов, а где можно по договорённости?', groups: ['Зона без экрана', 'Можно по договорённости'], items: [['Обед с семьёй', 0], ['Кровать перед сном', 0], ['Урок информатики', 1], ['Разговор с другом', 0], ['Видеозвонок бабушке', 1], ['Мультик в выходной', 1]], why: 'За едой, перед сном и в разговоре экраны мешают. Учёба и звонки близким — по договорённости.' },
        { type: 'case', story: 'Семья ужинает, а у всех рядом лежат телефоны и пиликают.', q: 'Что может предложить Мурлок?', a: [{ t: 'Убрать телефоны на время ужина', ok: true, why: 'Ужин без экранов — время поговорить друг с другом.' }, { t: 'Отвечать на сообщения прямо за едой', ok: false, why: 'Так и сытость заметить трудно, и разговора не получится.' }, { t: 'Промолчать', ok: 'mid', why: 'Можно, но идея «зоны без экранов» понравится многим — предложи!' }], why: 'Стол — хорошая зона без экранов.' },
        { type: 'order', q: 'Расставь «экранный» вечер по порядку.', items: ['Сделать уроки', 'Поиграть 30 минут по договорённости', 'Выключить экраны за час до сна', 'Почитать бумажную книгу', 'Лечь спать'], why: 'Сначала дела, потом игра, а за час до сна — без экранов.' }
